import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"同人","description":"焦氏易林注 - 同人","frontmatter":{"title":"同人","description":"焦氏易林注 - 同人"},"headers":[],"relativePath":"classics/jiaoyilin/013.md","filePath":"classics/jiaoyilin/013.md"}'),l={name:"classics/jiaoyilin/013.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="同人" tabindex="-1">同人 <a class="header-anchor" href="#同人" aria-label="Permalink to “同人”">​</a></h1><h3 id="同人-1" tabindex="-1">同人 <a class="header-anchor" href="#同人-1" aria-label="Permalink to “同人”">​</a></h3><h3 id="同人之乾" tabindex="-1">同人之乾 <a class="header-anchor" href="#同人之乾" aria-label="Permalink to “同人之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>一臂六手，不便於口。莫肯為用，利棄我走。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>○便於，從宋本，汲古作使堵，非。</p><h3 id="同人之坤" tabindex="-1">同人之坤 <a class="header-anchor" href="#同人之坤" aria-label="Permalink to “同人之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>獐鹿逐牧，飽歸其居，安寧無悔。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>○寧，從宋本，汲古作息，此用《同人》伏象。</p><h3 id="同人之屯" tabindex="-1">同人之屯 <a class="header-anchor" href="#同人之屯" aria-label="Permalink to “同人之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>鴻魚逆流，至人潛處。蓬蒿代柱，大屋顛僕。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮為鴻，坤為魚、為水、為逆，故曰鴻魚逆流。鴻，大也。坎為聖人，在下故曰潛處。坤為蓬蒿，震木為柱。坤在艮屋下，故曰代柱。坎陷故顛僕。○大，從宋元本，汲古作天屋。處，宋元本作渚，依汲古。僕，依《觀》之《需》校，各本皆作倒。《五行志》：&quot;眾逆同志，河魚逆流上&quot;，故林詞不吉。</p><h3 id="同人之蒙" tabindex="-1">同人之蒙 <a class="header-anchor" href="#同人之蒙" aria-label="Permalink to “同人之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>三羖五，相遇俱行。迷入空澤，經涉六駁，為所傷賊。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>伏兌為羊，故曰羖、曰。艮納丙，故曰三羖。坎納戊，故曰五。互震為行，坤為迷、為虛，故曰空澤，坎陷故曰澤。艮為駁，能食虎豹，然曰經涉則非獸也。《詩秦風》：&quot;隰有六駁&quot;，《傳》：駁，如馬。陸機雲：駁馬，梓榆也。樹皮青白駁犖，遙視似駁馬，故謂之駁。下章雲&quot;山有苞棣，隰有樹檖&quot;，皆言木，此不應言獸，茲林詞曰經涉六駁，為所傷賊，正用詩語。亦以六駁為木，與陸詁合。坎數六，故曰六駁。坎又為賊。○駁，依宋本，汲古訛駿。末句汲古作為賊所傷，依宋元本。為所傷賊者，言羊為駁木觸傷也。</p><h3 id="同人之需" tabindex="-1">同人之需 <a class="header-anchor" href="#同人之需" aria-label="Permalink to “同人之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>黃帝出遊，駕龍乘馬。東上泰山，南過齊魯，邦國鹹喜。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>離為黃，乾為帝、乾為馬，故曰駕龍乘馬。離為東，乾為山，兌為魯。伏坤為邦國。兌悅為喜。○東，依宋本，汲古訛乘。</p><h3 id="同人之訟" tabindex="-1">同人之訟 <a class="header-anchor" href="#同人之訟" aria-label="Permalink to “同人之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>履危不安，心欲東西。步走逐鹿，空無所得。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。震為履，坎為危，故履危不安。坎為心，為西，離為東，震為鹿、為走，坤虛，故空無所得。○坎西、離東證。</p><h3 id="同人之師" tabindex="-1">同人之師 <a class="header-anchor" href="#同人之師" aria-label="Permalink to “同人之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>望尚阿衡，太宰周公。藩屏湯武，立為侯王。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>伏離為望，伏巽為權衡。震為主、為周，故曰太宰周公。又乾為聖人，伏重乾，故聖人多也。坤為城、為屏藩，坎水故曰湯。震為武、為王，故曰湯武也。○太宰周公，依宋本，汲古作大半周公，皆訛字。</p><h3 id="同人之比" tabindex="-1">同人之比 <a class="header-anchor" href="#同人之比" aria-label="Permalink to “同人之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>白龍黑虎，起伏俱怒。戰於阪泉，蚩尤敗走，死於魚首。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《坎》。魚首，地名。坎為首，坤為魚，故曰魚首。○魚首，宋元本、汲古皆作魯首，非。敗走作走敗，茲從《益》之《比》較改。</p><h3 id="同人之小畜" tabindex="-1">同人之小畜 <a class="header-anchor" href="#同人之小畜" aria-label="Permalink to “同人之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>載石上山，步跌不前。頻眉之憂，不得所歡，長思憂嘆。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。艮為石、為山，坤為載，故曰載石上山。震為步，坎陷，故步跌不前。坎為憂，故曰頻眉，艮為眉也。震為歡，坎伏故不得。坎為憂。○頻，汲古訛顯，依宋元本。汲古無&quot;長思憂嘆&quot;四字，依宋元本。</p><h3 id="同人之履" tabindex="-1">同人之履 <a class="header-anchor" href="#同人之履" aria-label="Permalink to “同人之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>周德既成，行軸不傾。申酉昳暮，耄老衰去，箴石不佑。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為周，艮為成，故曰周德既成。震為行，坎為軸，坎平故不傾。坤居申，坎先居酉，故曰昳暮，言日至申酉而暮也。坤為老衰，坎為箴。艮為石，箴，針也，石，砭石，即石箴也。丁晏雲：《山海經》：&quot;高氏之山，其下多箴石&quot;，註：可以為砥針者是也。坤死，故雖有箴石，不能佑助。○行軸，依汲古，宋本作杼軸。申酉昳暮，依宋元本，汲古作&quot;中酉跌墓&quot;。</p><h3 id="同人之泰" tabindex="-1">同人之泰 <a class="header-anchor" href="#同人之泰" aria-label="Permalink to “同人之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>乘雲帶雨，與飛鳥俱。動舉千里，見我慈母。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為雲，兌為雨，震為乘，伏巽為帶。震為飛、為鳥、為舉動、為千里。坤為母、為我。兌為見。○坤為雲、兌為雨證，可解《易》。動舉，依宋本，汲古作舉動。</p><h3 id="同人之否" tabindex="-1">同人之否 <a class="header-anchor" href="#同人之否" aria-label="Permalink to “同人之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>賚貝贖狸，不聽我辭。繫於虎鬚，牽不得來。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《睽》。○艮為貝、為虎、為須證，可釋《易》。於，宋元本作我，依汲古。</p><h3 id="同人之同人" tabindex="-1">同人之同人 <a class="header-anchor" href="#同人之同人" aria-label="Permalink to “同人之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>櫜置山顛，銷鋒鑄刃。示不復用，天下大歡。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。坤為櫜，震為陵，乾亦為山陵、為顛。艮為鋒刃，艮覆故銷、故不用。坤為天下，震樂故曰大歡。○櫜置，宋本作密櫜，疑非，茲依汲古。</p><h3 id="同人之大有" tabindex="-1">同人之大有 <a class="header-anchor" href="#同人之大有" aria-label="Permalink to “同人之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>三翼飛來，是我逢時。俱行先至，多得大利。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>離數三，為飛、為翼，伏艮為時。坤為我，乾為行、為先，伏坤為利。○是，依宋本，汲古作字。</p><h3 id="同人之謙" tabindex="-1">同人之謙 <a class="header-anchor" href="#同人之謙" aria-label="Permalink to “同人之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>兩足四翼，飛入我國。寧我伯姊，與母相得。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坤數二，震為足、為翼，卦數四，故曰兩足四翼。震為飛，坤為國、為我。震為伯，伏巽為姊。坤為母。○我國，從汲古，宋本作家國。震數四證、為翼證。</p><h3 id="同人之豫" tabindex="-1">同人之豫 <a class="header-anchor" href="#同人之豫" aria-label="Permalink to “同人之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>按民呼池，玉杖文案。魚如白雲，一國獲願。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮手為按。坤為民、為河，震言坎水故曰呼池。呼池，即呼沱河。《周禮職方氏》作宓池，《戰國策》作呼沱，並同。震為玉、為杖，坤為文，艮為案，故曰玉杖文案。《後漢書禮儀志》：&quot;仲秋，縣道皆案民比戶，年七十授以玉杖，八十九十禮有加文案，乃養老加禮&quot;。坤為魚、為雲，震白，故曰魚如白雲。○按民呼池，依宋元本，汲古作案民湖池。文案，依宋本，汲古等本皆訛為天授。願，依宋本，與案為韻，汲古等本並訛為鯉。</p><h3 id="同人之隨" tabindex="-1">同人之隨 <a class="header-anchor" href="#同人之隨" aria-label="Permalink to “同人之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>季姬踟躕，望我城隅。終日至暮，不見齊侯，居止無憂。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>兌為季姬，艮止故踟躕。艮為日、為望、為城、為終，兌昧，故曰終日。巽為齊，震為諸侯，故曰齊侯，巽伏故不見。艮為居止，震樂，故無憂。陳樸園雲：案：《左傳》：&quot;齊桓公有長衛姬、少衛姬&quot;，《易林》所雲季姬即指少衛姬。《衛風靜女》雲：&quot;俟我於城隅&quot;，戴震雲：&quot;此媵俟迎之禮，諸侯惟親迎嫡夫人，媵則至乎城下，以俟迎者而後入&quot;，故《易林》《師》之《同人》雲&quot;結衿待時，終日至暮&quot;也，謂林詞全說《靜女》詩而與毛異。○望我，依宋元本，汲古作望還。居止，宋元本作君上，非，依汲古。君者，居之訛。上者，止之訛。</p><h3 id="同人之蠱" tabindex="-1">同人之蠱 <a class="header-anchor" href="#同人之蠱" aria-label="Permalink to “同人之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>龍渴求飲，黑雲影從。河伯捧觴，跪進酒漿，流潦滂滂。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為龍，兌口為飲。艮為求，互大坎為黑、為雲、為河。震為伯，故曰河伯。震為觴，艮手為捧。坎為酒漿、為流潦。○龍渴求飲，汲古作&quot;龍隅求泉&quot;，黑作置，均依宋元本。</p><h3 id="同人之臨" tabindex="-1">同人之臨 <a class="header-anchor" href="#同人之臨" aria-label="Permalink to “同人之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>出門逢患，與福為怨。更相擊刺，傷我手端。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為出，坤為門、為患，坤禍，故不福。伏艮為擊，對遯臨，正反艮，故相擊。兌為傷，伏艮為手，坤為我。○福，從宋元本，汲古等本皆訛為怒。</p><h3 id="同人之觀" tabindex="-1">同人之觀 <a class="header-anchor" href="#同人之觀" aria-label="Permalink to “同人之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>播天舞，光地乳。神所守，樂無咎。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為天、為手、為播、為舞。坤地，互艮為乳，艮為守，伏震為樂。坤為安。○此三字四句宋元本作&quot;播天舞地，神明所守，安樂無咎&quot;，汲古訛為&quot;播衣樂天，乾坤所命，安樂無咎&quot;，皆改作四字三句，茲依《剝》之《兌》宋本校。地乳，詳《泰》之《大有》。</p><h3 id="同人之噬嗑" tabindex="-1">同人之噬嗑 <a class="header-anchor" href="#同人之噬嗑" aria-label="Permalink to “同人之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>兩金相擊，勇氣鈞敵。終日大戰，不破不缺。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為金，正反震，故曰兩金。艮手為擊，正反艮，故曰相擊。震為勇，正反震，故曰鈞敵。艮為終，離為日，震為戰。兌為破缺，兌伏，故不破不缺。○勇氣鈞敵，依宋本，汲古等本作&quot;武勇敢敵&quot;，將林詞用覆之妙全失。</p><h3 id="同人之賁" tabindex="-1">同人之賁 <a class="header-anchor" href="#同人之賁" aria-label="Permalink to “同人之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>車雖駕，兩矧絕。馬奔出，雙輪脫。行不至，道遇害。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為車、為駕，伏巽為靷。兌卦數二，故曰兩靷。兌折故絕。震為馬、為奔出。坎為輪，兌卦數二，兌毀，故曰雙輪脫。坎陷故行不至。震為道，坎陷為害。○汲古作四字句而添二字作五句，為&quot;大車難駕，兩靷如繩，馬奔山後，輪脫不行，中道遇害。&quot;不有宋元本誰復知廬山真面，誰復知林詞奇妙如此。此與上六卦凡常本詞意失解者，皆賴宋元本復明，其可貴如此。</p><h3 id="同人之剝" tabindex="-1">同人之剝 <a class="header-anchor" href="#同人之剝" aria-label="Permalink to “同人之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>文山紫芝，雍梁朱草。長生和氣，王以為寶。公屍侑食，福祿來處。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《夬》。</p><h3 id="同人之復" tabindex="-1">同人之復 <a class="header-anchor" href="#同人之復" aria-label="Permalink to “同人之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>抱珠入口，為我畜寶。得吾所有，欣然嘉喜。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為口、為珠玉、為寶。坤為我、為吾、為畜。震為嘉喜。</p><h3 id="同人之無妄" tabindex="-1">同人之無妄 <a class="header-anchor" href="#同人之無妄" aria-label="Permalink to “同人之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>負牛上山，力盡行難。烈風雨雪，遮遏我前。中道復還，憂者得歡。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為負、為山、為牛，艮止，故力盡行難。互巽為風，乾為冰，故曰雨雪，艮止，故曰遮遏。艮為道，震反，故曰還。坎為憂，震樂，故曰得歡。○力盡，依汲古，宋本作劣。負牛，依宋本，汲古作負車。</p><h3 id="同人之大畜" tabindex="-1">同人之大畜 <a class="header-anchor" href="#同人之大畜" aria-label="Permalink to “同人之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>陶朱白圭，善賈息資。三致千金，德施上人。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮火，故曰陶，乾為大赤，故曰陶朱。震為玉、為白，故曰白圭。二人皆善治生致富。乾為富，故曰息資。伏巽為商賈，艮數三，乾為金、為千，故曰三致千金。乾為德，震為人。上人者，及人也。○人，依宋本，汲古作仁。</p><h3 id="同人之頤" tabindex="-1">同人之頤 <a class="header-anchor" href="#同人之頤" aria-label="Permalink to “同人之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>子鋤執麟，春秋作經。元聖將終，尼父悲心。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《同人》。○經，依釋文。元，依汲古，宋本作作元、作陰聖，非。</p><h3 id="同人之大過" tabindex="-1">同人之大過 <a class="header-anchor" href="#同人之大過" aria-label="Permalink to “同人之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>春日載陽，福履齊長。四時不忒，與樂為昌。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。震為春，乾為日、為陽。震為福履，巽齊，故曰齊長。艮為時，震數四，故曰四時。震為樂、為昌。○昌，依汲古，宋本作倡。</p><h3 id="同人之坎" tabindex="-1">同人之坎 <a class="header-anchor" href="#同人之坎" aria-label="Permalink to “同人之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>孔德如玉，出於幽谷。飛上喬木，鼓其羽翼，輝光照國。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《比》。○輝，依汲古，宋本作大。照國，依宋本，汲古及常本作耀光照目，非。</p><h3 id="同人之離" tabindex="-1">同人之離 <a class="header-anchor" href="#同人之離" aria-label="Permalink to “同人之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>區脫康居，慕仁入朝。湛露之歡，三爵畢恩。復歸穹廬，以安其居。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>註：詳《訟》之《恆》。○穹，宋本作窮，非。</p><h3 id="同人之鹹" tabindex="-1">同人之鹹 <a class="header-anchor" href="#同人之鹹" aria-label="Permalink to “同人之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>秋冬夜行，照覽星辰。道理利通，終身無患。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>兌為秋，乾為冬，互大坎為夜。艮為明、為觀，故曰照覽。艮為星辰、為道里。巽為利，艮為身、為終。坎為患，兌悅，故無患。○理，應作裡。無患，依汲古，宋本作何患。</p><h3 id="同人之恆" tabindex="-1">同人之恆 <a class="header-anchor" href="#同人之恆" aria-label="Permalink to “同人之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>鳴鵠抱子，見蛇何咎。室傢俱在，不失其所。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>註詳《否》之《鼎》，古鵠鶴通用。</p><h3 id="同人之遯" tabindex="-1">同人之遯 <a class="header-anchor" href="#同人之遯" aria-label="Permalink to “同人之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>安如泰山，福壽屢臻。雖有豺虎，不能危身。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為安、為壽。乾為福，艮為豺虎、為身，艮安故不危。○艮為身證。宋本如訛和。</p><h3 id="同人之大壯" tabindex="-1">同人之大壯 <a class="header-anchor" href="#同人之大壯" aria-label="Permalink to “同人之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>耆蒙睡眠，不知東西。歲君失理，命直為曲。王稱為寶。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>乾老故曰耆。《說文》：&quot;耆，老也&quot;。伏艮故曰蒙。耆蒙，即老少也。艮止坤迷，故曰睡眠。震東兌西，坤迷故不知。乾為君、為年，故曰歲君。坤為理，坤伏故失理。伏巽為命。孟氏逸象乾為直、為王、為寶。震口為稱。○耆蒙睡眠，依汲古，宋本作老目瞢眠。老目者，耆之訛，瞢，蒙之訛。歲君失理，命直為曲，王稱為寶。依汲古，宋本作&quot;君失理命，以直為傴，王珍為寶&quot;，非。此又汲古勝宋本處。</p><h3 id="同人之晉" tabindex="-1">同人之晉 <a class="header-anchor" href="#同人之晉" aria-label="Permalink to “同人之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>植璧秉圭，請命於河。周公克敏，沖人瘳愈。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>此用《同人》象。伏震為圭璧。艮手故曰秉、曰植。坎水坤水故曰河。艮為沖人。沖，幼也。震為公、為周。艮堅故瘳愈。○植璧秉圭，依宋本，汲古等本作載璧秉圭，非。植璧秉圭，金滕文。愈，依汲古。《說文》：&quot;病瘳也&quot;。徐鍇曰：今人作愈，非。由是證宋本作愈非。○《史記魯世家》：&quot;成王有疾，周公揃爪瀋河以祈病瘳&quot;。</p><h3 id="同人之明夷" tabindex="-1">同人之明夷 <a class="header-anchor" href="#同人之明夷" aria-label="Permalink to “同人之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>太王執政，歲熟民富。國家豐有，王者有喜。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為王，坤老，故曰太王。坤為政、為歲、為利，故曰歲熟。坤為民、為富、為國家、為豐。震為王，震喜。○太，依宋本，汲古作大，他本或作天。</p><h3 id="同人之家人" tabindex="-1">同人之家人 <a class="header-anchor" href="#同人之家人" aria-label="Permalink to “同人之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>訟爭相背，和氣不處。陰陽俱否，谷風無子。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>離為有言，故爭訟。坎為和，坎伏故不處。谷，毛詩作谷。傳雲：東風也。巽為風，離東，故曰東風。震為子，震伏故無子。谷風詩，毛傳謂刺夫婦失道，茲曰無子，蓋齊詩義也。○訟爭，依汲古，宋元本作爭訟。</p><h3 id="同人之睽" tabindex="-1">同人之睽 <a class="header-anchor" href="#同人之睽" aria-label="Permalink to “同人之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>齊魯爭言，戰於龍門。構怨結禍，三世不安。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>兌魯齊，似用半巽象。正反兩兌口相背，故曰爭言。餘詳《坤》之《離》。</p><h3 id="同人之蹇" tabindex="-1">同人之蹇 <a class="header-anchor" href="#同人之蹇" aria-label="Permalink to “同人之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>鹿得美草，鳴呼其友。九族和睦，不離邦域。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《同人》象。伏震為鹿、為草、為鳴，伏坤為族，震數九，故曰九族。震樂故和睦。坤為邦域。</p><h3 id="同人之解" tabindex="-1">同人之解 <a class="header-anchor" href="#同人之解" aria-label="Permalink to “同人之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>百裡南行，雖微復明。去虞適秦，為穆國卿。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>百裡奚自虞適秦，故曰南行。震為百、為南、為行。離為明，坎為憂虞，震樂故去虞。坎位西，故曰秦。○南，從宋元本，汲古訛難。微，從汲古，宋元本作徵，非。</p><h3 id="同人之損" tabindex="-1">同人之損 <a class="header-anchor" href="#同人之損" aria-label="Permalink to “同人之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>梅李冬實，國多寇賊。亂擾並作，王不能制。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《師》。</p><h3 id="同人之益" tabindex="-1">同人之益 <a class="header-anchor" href="#同人之益" aria-label="Permalink to “同人之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>府藏之富，王以賑貸。捕魚河海，笱網多得。巨蛇大暎，戰於國郊，君遂走逃。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《臨》。笱，依汲古，宋元訛苟。後三句定為衍文，應依《比》之《臨》校刪。</p><h3 id="同人之夬" tabindex="-1">同人之夬 <a class="header-anchor" href="#同人之夬" aria-label="Permalink to “同人之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>牡飛門啟，憂患大解。修福行善，不為身禍。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《兌》。○修福行善，依《需》之《兌》校，宋元本皆作&quot;去老乘馬&quot;，汲古無第三句。又牡，宋元本訛杜。</p><h3 id="同人之姤" tabindex="-1">同人之姤 <a class="header-anchor" href="#同人之姤" aria-label="Permalink to “同人之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>宜昌娶婦，東家歌舞，長樂歡喜。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>巽為震婦，震為娶、為昌、為東、為歌舞、為歡樂。伏坤為家。</p><h3 id="同人之萃" tabindex="-1">同人之萃 <a class="header-anchor" href="#同人之萃" aria-label="Permalink to “同人之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>正陽之央，甲氏以亡。禍及留籲，煙滅為墟。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>《左傳宣十六年》：&quot;正月，晉人滅赤狄甲氏及留籲&quot;，春正故曰正陽。央，中也，言正月之中也。伏乾為陽，互大坎為中。艮為甲，坤喪兌毀，故曰甲氏以亡。坤為禍，兌口為籲。坤為墟、為滅。○甲，汲古訛申，依宋元。</p><h3 id="同人之升" tabindex="-1">同人之升 <a class="header-anchor" href="#同人之升" aria-label="Permalink to “同人之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>鳧過稻廬，甘樂𪍿鰌。雖驅不去，田畯懷憂。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為鳧、為稻、為樂、為。𪍿，大麥也。巽為暎坤亦為魚。震為驅、為走，坤為田畯、為憂。○鳧，從汲古，宋元本作鳥，非。《詩小雅》：&quot;田畯至喜&quot;。</p><h3 id="同人之困" tabindex="-1">同人之困 <a class="header-anchor" href="#同人之困" aria-label="Permalink to “同人之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>跛踦俱行，日暮車傷，失旅乏糧。通《賁》。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>坎蹇故曰跛踦。震為行，離為日，坎為夜，故曰日暮。震為車，坎折故傷。震為行旅、為糧，兌毀，故曰失旅乏糧。</p><h3 id="同人之井" tabindex="-1">同人之井 <a class="header-anchor" href="#同人之井" aria-label="Permalink to “同人之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>龍門水穴，流行不害。民安其土，君臣相保。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。震為龍，艮為門、為穴，坎水為流，流順故不害。坎為民，艮為安、為土，震君艮臣。○艮為臣證。○水，汲古作小，依宋元本。《集韻》害，音曷，與穴韻。</p><h3 id="同人之革" tabindex="-1">同人之革 <a class="header-anchor" href="#同人之革" aria-label="Permalink to “同人之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>山陵四塞，遏我徑路。欲前不得，復還故處。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。艮為山、為塞、為遏、為徑路。坎陷艮止，故欲前不得。震卦數四，故曰四塞。○四，依宋元本，汲古作西，前作全，非。</p><h3 id="同人之鼎" tabindex="-1">同人之鼎 <a class="header-anchor" href="#同人之鼎" aria-label="Permalink to “同人之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>兩虎爭鬬，血流漂杵。城郭空虛，蒿藜塞道。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。艮為虎，坤數二，故曰兩虎。又正反艮，故曰爭鬬。坎為血、為杵，艮為城郭，坤為空虛，震為藜蒿，艮為道。</p><h3 id="同人之震" tabindex="-1">同人之震 <a class="header-anchor" href="#同人之震" aria-label="Permalink to “同人之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>依叔牆隅，志下心勞。楚亭晨食，韓子低頭。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為牆、為叔、為依。坎為志、為心、為勞。震為楚、為晨、為食，艮為亭，坎為信，故曰韓子。韓子者，韓信也。艮為頭，坎下首，故低頭。《史記淮陰侯傳》：&quot;常數從南昌亭長寄食，亭長妻患之，不為具食，信怒絕去&quot;。○叔，依宋元，汲古作東。</p><h3 id="同人之艮" tabindex="-1">同人之艮 <a class="header-anchor" href="#同人之艮" aria-label="Permalink to “同人之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>龍生無常，或託空桑。憑乘風雲，為堯立功。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>震為龍、為生、為桑，互大離，離虛，故曰空桑。坎為雲，伏巽為風。震為乘，艮手為憑。震為帝，故曰堯。按：皇甫謐雲：伊尹生於空桑，堯時諸臣。禹生石紐，見史記註。無生空桑者，西漢時古籍多，或別有所據。○空桑，依汲古，宋元本作葉。</p><h3 id="同人之漸" tabindex="-1">同人之漸 <a class="header-anchor" href="#同人之漸" aria-label="Permalink to “同人之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>魁行搖尾，逐雲吹水。汙泥為陸，下田宜稷。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為星、為尾。魁，北斗星也。巽進退，故曰搖尾。坎為雲，水兌口向坎，故曰逐雲吹水。坎為汙泥，坎陷故亦為下田。艮為陸，巽為稷，言宜種黍稷也。○水，汲古作火，依宋元本。宜稷，多作為稷，依《巽》之《師》校。</p><h3 id="同人之歸妹" tabindex="-1">同人之歸妹 <a class="header-anchor" href="#同人之歸妹" aria-label="Permalink to “同人之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>跛踦相隨，日暮牛罷。陵遲後旅，失利亡雌。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>坎蹇故跛踦。離為日、為牛。坎夜坎勞，故曰日暮牛罷。震為商旅、為後，巽為利，巽伏，故曰失利亡雌。巽為震婦，故曰雌也。</p><h3 id="同人之豐" tabindex="-1">同人之豐 <a class="header-anchor" href="#同人之豐" aria-label="Permalink to “同人之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>三人俱行，北求大牂。長孟病足，倩季負糧。柳下之寶，不失我邦。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震為人、為行，數三，故曰三人俱行。互大坎為北，兌為羊，震為長孟、為足，坎病，故曰病足。按：《家語》：&quot;叔梁紇之妾生孟皮，孟皮病足&quot;。季，季路也。《家語》子路曰：&quot;吾為親負米百裡之外&quot;。互巽為糧，伏艮為季、為負。震為柳，伏坤為下、為邦。○糧，宋元、汲古作囊，依汲古《革》之《恆》校。孟，從宋元，汲古作子。寶，從宋元，汲古作責，非。按：《呂氏春秋》：&quot;齊伐魯，求岑鼎，魯以他鼎往，齊侯曰：柳下季謂是則因受之，魯侯請柳下季，季曰：君以賂欲免國也，臣亦有國，破臣之國以免君之國，所不願也，魯侯乃以真岑鼎往&quot;。我邦，各本皆作驪黃，依汲古《渙》之《豫》校。</p><h3 id="同人之旅" tabindex="-1">同人之旅 <a class="header-anchor" href="#同人之旅" aria-label="Permalink to “同人之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>鳳凰在左，麒麟處右。仁聖相遇，伊呂集聚。傷害不至，時無殃咎，福為我母。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>離為鳳凰、為麒麟。離東為左，兌西為右。坎為聖、為集聚。兌口為伊。巽為齊、為呂。○處右，從宋元，汲古作在右。</p><h3 id="同人之巽" tabindex="-1">同人之巽 <a class="header-anchor" href="#同人之巽" aria-label="Permalink to “同人之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>乘筏渡海，雖深不殆。曾孫皇祖，纍纍俱在。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏震為筏、為乘，互大坎為海、為深，兌悅故不殆。伏艮為曾孫、為祖。○海，從宋元，汲古作河，不協，非。</p><h3 id="同人之兌" tabindex="-1">同人之兌 <a class="header-anchor" href="#同人之兌" aria-label="Permalink to “同人之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>比目四翼，來安吾國。齎福上堂，與我同床。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《離》。</p><h3 id="同人之渙" tabindex="-1">同人之渙 <a class="header-anchor" href="#同人之渙" aria-label="Permalink to “同人之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>娶於薑呂，駕迎新婦。少齊在門，夫子悅喜。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《渙》。呂、齊，汲古作女、作妻，依宋元本。</p><h3 id="同人之節" tabindex="-1">同人之節 <a class="header-anchor" href="#同人之節" aria-label="Permalink to “同人之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>螟蟲為賊，害我稼穡。盡禾殫麥，秋無所得。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>坎為賊、為害，伏巽為螟蟲。震為禾稼，兌正秋，兌毀折，故秋無所得。○盡禾，汲古作冬禾，依宋元本。</p><h3 id="同人之中孚" tabindex="-1">同人之中孚 <a class="header-anchor" href="#同人之中孚" aria-label="Permalink to “同人之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>衣裳顛倒，為王來呼。成就東周，邦國大休。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為衣裳，正反震，故曰顛倒。震為王、為呼、為東周，艮為成、為邦國。按：《齊風》：&quot;東方未明，顛倒衣裳；顛之倒之，自公召之&quot;，《毛詩敘》謂朝廷興居無節，焦意似指太公佐周，與毛異。</p><h3 id="同人之小過" tabindex="-1">同人之小過 <a class="header-anchor" href="#同人之小過" aria-label="Permalink to “同人之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>王孫季子，相與為友。明允篤誠，升擢薦舉。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為王，艮為孫、為季子、為友。震為明允，艮為篤誠，震為薦舉，艮手為擢。詞似用《史記》舜舉八元八愷事。○篤，元本訛駕，依宋本、汲古。薦，依汲古，宋元本皆訛慶。</p><h3 id="同人之既濟" tabindex="-1">同人之既濟 <a class="header-anchor" href="#同人之既濟" aria-label="Permalink to “同人之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>踴泉滑滑，流行不絕。汙為江海，敗毀邑里，家無所處。聞虎不懼，向我笑喜。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>坎為泉，重坎，故流行不絕、故汙為江海。坤為邑里，三坤爻隔絕，故雲敗毀。坎為懼，虎與笑喜蓋用半象。○踴，汲古作漏，依宋元。懼，從宋元，汲古作悖。又按：似用《同人》伏象。</p><h3 id="同人之未濟" tabindex="-1">同人之未濟 <a class="header-anchor" href="#同人之未濟" aria-label="Permalink to “同人之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>桑扈竊脂，啄粟不宜。亂政無常，使心孔明。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>離為鳥，故曰桑扈竊脂。坎為竊、為脂。竊脂，即桑扈，一物也。《左傳襄四年》：&quot;桑扈竊脂為蠶驅雀者也&quot;，《詩小雅》：&quot;交交桑扈&quot;，餘似用半象。○扈，宋元本作戶，從汲古。心，依宋元本，汲古作我。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
